function LogoMark({
  fill,
  className,
  style,
}: Readonly<{ fill: string; className?: string; style?: CSSProperties }>) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 2048 682"
      aria-label={BRAND.name}
      style={style}
      className={cn("inline-block h-8 w-auto shrink-0", className)}
    >
      <path fill={fill} fillRule="evenodd" d={PATH_D} />
    </svg>
  );
}

export function BrandLogo({ className, tone = "auto", style }: Readonly<BrandLogoProps>) {
  if (tone === "auto") {
    // Use html.dark / html.light (set by the boot script) with classes that do not
    // depend on Tailwind being loaded — otherwise both marks stack after a bad deploy.
    return (
      <>
        <LogoMark
          fill={FILL.purple}
          style={style}
          className={cn("brand-logo-light", className)}
        />
        <LogoMark
          fill={FILL.yellow}
          style={style}
          className={cn("brand-logo-dark", className)}
        />
      </>
    );
  }

  return <LogoMark fill={FILL[tone]} style={style} className={className} />;
}
